package vmcompat;
import java.nio.*;import java.nio.file.*;import org.lwjgl.*;import org.lwjgl.glfw.*;import org.lwjgl.opengl.*;
/** Mixed static model-array and dynamic framebuffer/depth consumer in the existing GL runner. */
public final class PartialPackingTests {
 static int producer,colour,depth,program,white;static boolean selective;
 static void check(boolean b,String text){if(!b)throw new AssertionError(text+" / GL="+GL11.glGetError());}
 static void frame(int i){GL30.glBindFramebuffer(GL30.GL_FRAMEBUFFER,producer);GL11.glClearColor((i%5)/4f,0,0,1);GL11.glClearDepth(.25);Gl41.glClear(GL11.GL_COLOR_BUFFER_BIT|GL11.GL_DEPTH_BUFFER_BIT);GL30.glBindFramebuffer(GL30.GL_FRAMEBUFFER,0);GL11.glViewport(0,0,16,16);Shaders.glUseProgram(program);Draws.glDrawArrays(GL11.GL_TRIANGLES,0,3);}
 public static void main(String[] args)throws Exception{selective=Boolean.parseBoolean(Options.value("packingArrayOnly","true"));check(GLFW.glfwInit(),"GLFW");GLFW.glfwWindowHint(GLFW.GLFW_VISIBLE,0);long window=Context.createWindow(16,16,"Selective sampler packing",0,0);Context.makeCurrent(window);Context.capabilities();
  program=StorageBuffersTests.program("#version 330\nuniform sampler2D images[16];uniform sampler2D scene;uniform sampler2D depthTex;out vec4 c;void main(){float r=0.;for(int i=0;i<16;i++)r+=texture(images[i],vec2(.5)).r;c=vec4((r+texture(scene,vec2(.5)).r+texture(depthTex,vec2(.5)).r)/18.,0,0,1);}");Shaders.glUseProgram(program);
  white=Textures.glCreateTextures(GL11.GL_TEXTURE_2D);Textures.glTextureStorage2D(white,1,GL11.GL_RGBA8,16,16);Textures.glTextureParameteri(white,GL11.GL_TEXTURE_MIN_FILTER,GL11.GL_NEAREST);Textures.glTextureParameteri(white,GL11.GL_TEXTURE_MAG_FILTER,GL11.GL_NEAREST);ByteBuffer data=BufferUtils.createByteBuffer(1024);for(int i=0;i<1024;i++)data.put(i,(byte)255);Textures.glTextureSubImage2D(white,0,0,0,16,16,GL11.GL_RGBA,GL11.GL_UNSIGNED_BYTE,data);for(int i=0;i<16;i++){Samplers.glActiveTexture(GL13.GL_TEXTURE0+i);Samplers.glBindTexture(GL11.GL_TEXTURE_2D,white);Samplers.glUniform1i(Shaders.glGetUniformLocation(program,"images["+i+"]"),i);}
  colour=Textures.glCreateTextures(GL11.GL_TEXTURE_2D);Textures.glTextureStorage2D(colour,1,GL11.GL_RGBA8,256,256);depth=Textures.glCreateTextures(GL11.GL_TEXTURE_2D);Textures.glTextureStorage2D(depth,1,GL30.GL_DEPTH_COMPONENT32F,256,256);for(int tex:new int[]{colour,depth}){Textures.glTextureParameteri(tex,GL11.GL_TEXTURE_MIN_FILTER,GL11.GL_NEAREST);Textures.glTextureParameteri(tex,GL11.GL_TEXTURE_MAG_FILTER,GL11.GL_NEAREST);}Samplers.glActiveTexture(GL13.GL_TEXTURE0+16);Samplers.glBindTexture(GL11.GL_TEXTURE_2D,colour);Samplers.glUniform1i(Shaders.glGetUniformLocation(program,"scene"),16);Samplers.glActiveTexture(GL13.GL_TEXTURE0+17);Samplers.glBindTexture(GL11.GL_TEXTURE_2D,depth);Samplers.glUniform1i(Shaders.glGetUniformLocation(program,"depthTex"),17);
  producer=GL30.glGenFramebuffers();Gl41.glNamedFramebufferTextureLayer(producer,GL30.GL_COLOR_ATTACHMENT0,colour,0,0);Gl41.glNamedFramebufferTextureLayer(producer,GL30.GL_DEPTH_ATTACHMENT,depth,0,0);
  for(int i=0;i<4;i++){frame(i);FloatBuffer pixel=BufferUtils.createFloatBuffer(4);GL11.glReadPixels(8,8,1,1,GL11.GL_RGBA,GL11.GL_FLOAT,pixel);check(Math.abs(pixel.get(0)-(16+(i%5)/4f+.25f)/18f)<.008,"mixed static/dynamic pixels");}for(int i=0;i<30;i++)frame(i);GL11.glFinish();long[] before=Counters.snapshot();long at=System.nanoTime();for(int i=0;i<200;i++)frame(i);GL11.glFinish();long[] after=Counters.snapshot();long copied=after[Counters.Key.PACK_BYTES.ordinal()]-before[Counters.Key.PACK_BYTES.ordinal()],uploads=after[Counters.Key.PACK_UPLOADS.ordinal()]-before[Counters.Key.PACK_UPLOADS.ordinal()];double wall=(System.nanoTime()-at)/1e6/200;
  if(Counters.ENABLED)check(selective?copied==0&&uploads==0:copied>200L*1024*1024&&uploads==200,"dynamic framebuffer updates must not invalidate selected static-array table");Files.writeString(Path.of(System.getProperty("vmcompat.resultDir"),"partial-packing.json"),"{\"selective\":"+selective+",\"blocks\":200,\"pack_uploads\":"+uploads+",\"pack_bytes\":"+copied+",\"completed_ms_per_block\":"+wall+",\"game_fps\":null}\n");
  for(int i=0;i<1024;i++)data.put(i,(byte)(i%4==0?64:0));Textures.glTextureSubImage2D(white,0,0,0,16,16,GL11.GL_RGBA,GL11.GL_UNSIGNED_BYTE,data);frame(0);FloatBuffer changed=BufferUtils.createFloatBuffer(4);GL11.glReadPixels(8,8,1,1,GL11.GL_RGBA,GL11.GL_FLOAT,changed);check(Math.abs(changed.get(0)-(16*64/255f+.25f)/18f)<.008,"static-array mutation invalidates only its table");
  Shaders.glDeleteProgram(program);Textures.glDeleteTextures(new int[]{white,colour,depth});Gl41.glDeleteFramebuffers(producer);Context.destroyWindow(window);GLFW.glfwTerminate();System.out.println("PASS mixed static-array and dynamic colour/depth, selective="+selective+", uploads="+uploads+", bytes="+copied+", ms/block="+wall);
 }
}
